    'a': 1,
    'b': [2, 3, {'c': 4}],
    'd': {'e': 5, 'f': [6, 7]}
}
```

**Sample Output:**
```python
copied_dict = {
    'a': 1,
    'b': [2, 3, {'c': 4}],
    'd': {'e': 5, 'f': [6, 7]}
}
```

**Note:** Modifying `copied_dict` should not affect `original_dict`.
Your code should pass these tests:

assert deep_copy({}) == {}
assert deep_copy({'a': 1, 'b': 2}) == {'a': 1, 'b': 2}
assert deep_copy({'a': {'b': 2}}) == {'a': {'b': 2}}
assert deep_copy({'a': [1, 2, 3]}) == {'a': [1, 2, 3]}
assert deep_copy([{'a': 1}, {'b': 2}]) == [{'a': 1}, {'b': 2}]
assert deep_copy({'a': {'b': {'c': 3}}}) == {'a': {'b': {'c': 3}}}
assert deep_copy({'a': [1, {'b': 2}]}) == {'a': [1, {'b': 2}]}
assert deep_copy([1, [2, [3, 4]]]) == [1, [2, [3, 4]]]
assert deep_copy({'a': 1, 'b': {'c': [2, 3, {'d': 4}]}}) == {'a': 1, 'b': {'c': [2, 3, {'d': 4}]}}
