assert flatten_json({"x": {"y": {"z": 4}}}) == {"x_y_z": 4}
assert flatten_json({"key": "value"}) == {"key": "value"}
assert flatten_json({}) == {}
assert flatten_json({"level1": {"level2": {"level3": {"level4": 5}}}}) == {"level1_level2_level3_level4": 5}
assert flatten_json({"a": 1, "b": 2, "c": 3}) == {"a": 1, "b": 2, "c": 3}
