assert nest_dict({'x/y': 10, 'x/z': 20, 'w': 30}) == {'x': {'y': 10, 'z': 20}, 'w': 30}
assert nest_dict({'m/n/o': 100, 'm/n/p': 200, 'm/q': 300}) == {'m': {'n': {'o': 100, 'p': 200}, 'q': 300}}
assert nest_dict({'a': 1, 'a/b': 2, 'a/b/c': 3}) == {'a': {'b': {'c': 3}}}
assert nest_dict({'a/b': 1, 'a': 2}) == {'a': 2}
assert nest_dict({'a/b/c/d': 1, 'a/b/c/e': 2, 'a/b/f': 3}) == {'a': {'b': {'c': {'d': 1, 'e': 2}, 'f': 3}}}
assert nest_dict({}) == {}
assert nest_dict({'single': 'value'}) == {'single': 'value'}
assert nest_dict({'conflict': 1, 'conflict/sub': 2}) == {'conflict': {'sub': 2}}
assert nest_dict({'level1/level2/level3/level4': 'deep'}) == {'level1': {'level2': {'level3': {'level4': 'deep'}}}}
